import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        testAddressMapping();
        testProfileMappingAndCopying();
        testImmutableEmailInputs();
        testMalformedInputs();
    }

    private static void testAddressMapping() {
        Solution.Address address = Solution.mapAddress(new Solution.AddressCommand(null, ""));
        equals(null, address.getStreet(), "null street copied");
        equals("", address.getCity(), "empty city copied");

        Solution.Address normal = Solution.mapAddress(new Solution.AddressCommand("  Main St  ", "Bengaluru"));
        equals("  Main St  ", normal.getStreet(), "street copied exactly");
        equals("Bengaluru", normal.getCity(), "city copied exactly");
    }

    private static void testProfileMappingAndCopying() {
        ArrayList<String> sourceEmails = new ArrayList<String>();
        sourceEmails.add("a@example.com");
        sourceEmails.add("");
        sourceEmails.add("a@example.com");
        Solution.NewProfileCommand command = new Solution.NewProfileCommand(
                null, Integer.MIN_VALUE, new Solution.AddressCommand("Road", "City"), sourceEmails);

        Solution.Profile profile = Solution.mapProfile(command);
        equals(null, profile.getName(), "null name copied");
        equals(Integer.valueOf(Integer.MIN_VALUE), Integer.valueOf(profile.getAge()), "minimum age copied");
        equals("Road", profile.getAddress().getStreet(), "nested street mapped");
        equals("City", profile.getAddress().getCity(), "nested city mapped");
        equals(Arrays.asList("a@example.com", "", "a@example.com"), profile.getEmails(),
                "order, empty strings, and duplicates preserved");

        sourceEmails.set(0, "changed@example.com");
        sourceEmails.clear();
        equals(Arrays.asList("a@example.com", "", "a@example.com"), profile.getEmails(),
                "profile snapshots command list");
        expectUnsupported(new Action() {
            public void run() { profile.getEmails().add("x@example.com"); }
        }, "profile email list");
    }

    private static void testImmutableEmailInputs() {
        Solution.Profile empty = Solution.mapProfile(new Solution.NewProfileCommand(
                "name", Integer.MAX_VALUE, new Solution.AddressCommand("", null), List.<String>of()));
        check(empty.getEmails().isEmpty(), "List.of empty input accepted");
        equals(Integer.valueOf(Integer.MAX_VALUE), Integer.valueOf(empty.getAge()), "maximum age copied");
        equals("", empty.getAddress().getStreet(), "empty street allowed");
        equals(null, empty.getAddress().getCity(), "null city allowed");

        Solution.Profile single = Solution.mapProfile(new Solution.NewProfileCommand(
                "n", -1, new Solution.AddressCommand("s", "c"), List.of("a@b")));
        equals(List.of("a@b"), single.getEmails(), "singleton List.of accepted");

        Solution.Profile duplicates = Solution.mapProfile(new Solution.NewProfileCommand(
                "n", 0, new Solution.AddressCommand("s", "c"), List.of("a@b", "a@b")));
        equals(List.of("a@b", "a@b"), duplicates.getEmails(), "immutable duplicate list preserved");
    }

    private static void testMalformedInputs() {
        expectIllegalArgument(new Action() {
            public void run() { Solution.mapAddress(null); }
        }, "null address command");
        expectIllegalArgument(new Action() {
            public void run() { Solution.mapProfile(null); }
        }, "null profile command");
        expectIllegalArgument(new Action() {
            public void run() {
                Solution.mapProfile(new Solution.NewProfileCommand("n", 0, null, List.<String>of()));
            }
        }, "null nested address");
        expectIllegalArgument(new Action() {
            public void run() {
                Solution.mapProfile(new Solution.NewProfileCommand(
                        "n", 0, new Solution.AddressCommand("s", "c"), null));
            }
        }, "null email list");

        final List<String> withNull = new ArrayList<String>();
        withNull.add("valid");
        withNull.add(null);
        withNull.add("later");
        expectIllegalArgument(new Action() {
            public void run() {
                Solution.mapProfile(new Solution.NewProfileCommand(
                        "n", 0, new Solution.AddressCommand("s", "c"), withNull));
            }
        }, "null email element");
        equals(Arrays.asList("valid", null, "later"), withNull, "invalid input not mutated");
    }

    private interface Action { void run(); }

    private static void expectIllegalArgument(Action action, String label) {
        try {
            action.run();
            throw new AssertionError("Expected IllegalArgumentException: " + label);
        } catch (IllegalArgumentException expected) {
            // expected
        }
    }

    private static void expectUnsupported(Action action, String label) {
        try {
            action.run();
            throw new AssertionError("Expected unmodifiable " + label);
        } catch (UnsupportedOperationException expected) {
            // expected
        }
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void equals(Object expected, Object actual, String message) {
        if (expected == null ? actual != null : !expected.equals(actual)) {
            throw new AssertionError(message + ": expected=" + expected + ", actual=" + actual);
        }
    }
}

