import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

public class SolutionTest {
    public static void main(String[] args) {
        testBuiltInStagesAndOrder();
        testLocaleIndependentUppercase();
        testEmptyAndImmutableWorkflows();
        testDefensiveCopy();
        testValidationAndNullStageResult();
    }

    private static void testBuiltInStagesAndOrder() {
        List<Solution.Stage> stages = Arrays.<Solution.Stage>asList(
                new Solution.TrimStage(), new Solution.UpperStage());
        equals("HELLO WORLD", Solution.execute("  Hello World  ", stages), "trim then uppercase");
        equals("x123", Solution.execute("x", Arrays.<Solution.Stage>asList(
                new AppendStage("1"), new AppendStage("2"), new AppendStage("3"))),
                "stages applied in list order");
    }

    private static void testLocaleIndependentUppercase() {
        Locale original = Locale.getDefault();
        try {
            Locale.setDefault(new Locale("tr", "TR"));
            equals("I", new Solution.UpperStage().apply("i"), "uppercase independent of default locale");
        } finally {
            Locale.setDefault(original);
        }
    }

    private static void testEmptyAndImmutableWorkflows() {
        String input = "  unchanged  ";
        equals(input, Solution.execute(input, Collections.<Solution.Stage>emptyList()),
                "empty stage list returns original content");
        equals(input, new Solution.Workflow(List.<Solution.Stage>of()).run(input),
                "Workflow accepts empty List.of");

        Solution.Stage stage = new AppendStage("!");
        Solution.Workflow singleton = new Solution.Workflow(List.of(stage));
        equals("known!", singleton.run("known"), "Workflow accepts singleton List.of");
        equals("known!", Solution.execute("known", List.of(stage)), "execute accepts singleton List.of");
    }

    private static void testDefensiveCopy() {
        ArrayList<Solution.Stage> callerStages = new ArrayList<Solution.Stage>();
        callerStages.add(new AppendStage("A"));
        Solution.Workflow workflow = new Solution.Workflow(callerStages);
        callerStages.clear();
        callerStages.add(new AppendStage("B"));
        equals("xA", workflow.run("x"), "workflow snapshots caller list");
    }

    private static void testValidationAndNullStageResult() {
        expectIllegalArgument(new Action() {
            public void run() { new Solution.Workflow(null); }
        }, "null list");
        expectIllegalArgument(new Action() {
            public void run() {
                List<Solution.Stage> stages = new ArrayList<Solution.Stage>();
                stages.add(new AppendStage("x"));
                stages.add(null);
                new Solution.Workflow(stages);
            }
        }, "null stage");
        expectIllegalArgument(new Action() {
            public void run() { new Solution.Workflow(List.<Solution.Stage>of()).run(null); }
        }, "null input with no stages");
        expectIllegalArgument(new Action() {
            public void run() {
                Solution.execute("x", Arrays.<Solution.Stage>asList(new AppendStage("a"), new NullStage()));
            }
        }, "stage returning null");
        expectIllegalArgument(new Action() {
            public void run() { Solution.execute("x", null); }
        }, "execute with null stages");
    }

    private static final class AppendStage implements Solution.Stage {
        private final String suffix;
        AppendStage(String suffix) { this.suffix = suffix; }
        public String apply(String input) { return input + suffix; }
    }

    private static final class NullStage implements Solution.Stage {
        public String apply(String input) { return null; }
    }

    private interface Action { void run(); }

    private static void expectIllegalArgument(Action action, String label) {
        try {
            action.run();
            throw new AssertionError("Expected IllegalArgumentException: " + label);
        } catch (IllegalArgumentException expected) {
            // expected
        }
    }

    private static void equals(Object expected, Object actual, String message) {
        if (expected == null ? actual != null : !expected.equals(actual)) {
            throw new AssertionError(message + ": expected=" + expected + ", actual=" + actual);
        }
    }
}

