import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicReference;

public class SolutionTest {
    public static void main(String[] args) throws Exception {
        testValidationBoundariesAndAtomicFailure();
        testOrderingAndRendering();
        testClearAndFreshSnapshots();
        testConcurrentOperations();
    }

    private static void testValidationBoundariesAndAtomicFailure() {
        Solution.clear();
        check(Solution.write("A", ""), "one-character key and empty value valid");
        equals("", Solution.read("A"), "empty value readable");

        String key32 = repeat('Z', 32);
        String value256 = repeat('v', 256);
        check(Solution.write(key32, value256), "maximum lengths valid");
        equals(value256, Solution.read(key32), "boundary value retained");
        check(!Solution.write(repeat('Z', 33), "x"), "33-character key invalid");
        check(!Solution.write("B", repeat('v', 257)), "257-character value invalid");

        check(Solution.write("Keep", "old"), "baseline write");
        check(!Solution.write("Keep", null), "null overwrite rejected");
        equals("old", Solution.read("Keep"), "invalid overwrite is atomic");

        String[] invalidKeys = {null, "", "a_b", "a-b", "a b", "é", "A\n", "１２"};
        for (String key : invalidKeys) {
            check(!Solution.write(key, "x"), "invalid key rejected: " + String.valueOf(key));
            equals(null, Solution.read(key), "invalid read returns null: " + String.valueOf(key));
        }
        check(!Solution.write("Valid", null), "null value rejected");
        check(Solution.write("aZ09", "left=middle=right"), "ASCII key and equals value valid");
        equals("left=middle=right", Solution.read("aZ09"), "equals signs preserved");
        equals(null, Solution.read("Absent"), "absent read returns null");
    }

    private static void testOrderingAndRendering() {
        Solution.clear();
        check(Solution.write("A", "z"), "write A");
        check(Solution.write("A0", "a"), "write A0");
        check(Solution.write("a", "0"), "write lowercase a");
        check(Solution.write("B", "contains=value"), "write B");
        assertArrayEquals(new String[] {"A=z", "A0=a", "B=contains=value", "a=0"},
                Solution.snapshot(), "sorted by original keys");
        check(Solution.write("A", "new"), "overwrite succeeds");
        assertArrayEquals(new String[] {"A=new", "A0=a", "B=contains=value", "a=0"},
                Solution.snapshot(), "overwrite has no duplicate");
    }

    private static void testClearAndFreshSnapshots() {
        String[] first = Solution.snapshot();
        String original = first[0];
        first[0] = "corrupted";
        String[] second = Solution.snapshot();
        equals(original, second[0], "snapshot array detached");
        check(first != second, "snapshot arrays distinct");
        Solution.clear();
        assertArrayEquals(new String[0], Solution.snapshot(), "empty snapshot after clear");
        equals(null, Solution.read("A"), "clear removes entries");
    }

    private static void testConcurrentOperations() throws Exception {
        Solution.clear();
        final int threadCount = 8;
        final int entriesPerThread = 100;
        final CountDownLatch ready = new CountDownLatch(threadCount);
        final CountDownLatch start = new CountDownLatch(1);
        final CountDownLatch done = new CountDownLatch(threadCount);
        final AtomicReference<Throwable> failure = new AtomicReference<Throwable>();
        Thread[] workers = new Thread[threadCount];

        for (int t = 0; t < threadCount; t++) {
            final int writer = t;
            workers[t] = new Thread(new Runnable() {
                public void run() {
                    try {
                        ready.countDown();
                        start.await();
                        for (int i = 0; i < entriesPerThread; i++) {
                            String key = key(writer, i);
                            String value = value(writer, i);
                            if (!Solution.write(key, value)) {
                                throw new AssertionError("valid concurrent write rejected: " + key);
                            }
                            if (!value.equals(Solution.read(key))) {
                                throw new AssertionError("concurrent read mismatch: " + key);
                            }
                        }
                    } catch (Throwable error) {
                        failure.compareAndSet(null, error);
                    } finally {
                        done.countDown();
                    }
                }
            });
            workers[t].start();
        }

        ready.await();
        validateConcurrentSnapshot(Solution.snapshot(), threadCount, entriesPerThread);
        start.countDown();
        do {
            validateConcurrentSnapshot(Solution.snapshot(), threadCount, entriesPerThread);
        } while (done.getCount() != 0);

        for (Thread worker : workers) worker.join();
        Throwable workerFailure = failure.get();
        if (workerFailure != null) throw new AssertionError("worker failed", workerFailure);

        String[] finalSnapshot = Solution.snapshot();
        validateConcurrentSnapshot(finalSnapshot, threadCount, entriesPerThread);
        equals(Integer.valueOf(threadCount * entriesPerThread), Integer.valueOf(finalSnapshot.length),
                "all concurrent writes retained");
        Map<String, String> finalEntries = parse(finalSnapshot);
        for (int t = 0; t < threadCount; t++) {
            for (int i = 0; i < entriesPerThread; i++) {
                equals(value(t, i), finalEntries.get(key(t, i)), "exact final entry " + key(t, i));
            }
        }
    }

    private static void validateConcurrentSnapshot(String[] snapshot, int writers, int limit) {
        Set<String> keys = new HashSet<String>();
        String previous = null;
        Map<String, String> entries = parse(snapshot);
        for (String rendered : snapshot) {
            int separator = rendered.indexOf('=');
            check(separator > 0, "rendered entry has key separator");
            String key = rendered.substring(0, separator);
            check(keys.add(key), "snapshot keys unique: " + key);
            if (previous != null) check(previous.compareTo(key) < 0, "snapshot key ordering");
            previous = key;
        }
        for (int t = 0; t < writers; t++) {
            boolean gapSeen = false;
            for (int i = 0; i < limit; i++) {
                String key = key(t, i);
                if (entries.containsKey(key)) {
                    check(!gapSeen, "writer snapshot is a prefix for writer " + t);
                    equals(value(t, i), entries.get(key), "snapshot value for " + key);
                } else {
                    gapSeen = true;
                }
            }
        }
    }

    private static Map<String, String> parse(String[] snapshot) {
        Map<String, String> result = new HashMap<String, String>();
        for (String rendered : snapshot) {
            int separator = rendered.indexOf('=');
            check(separator > 0, "entry must contain equals after key");
            result.put(rendered.substring(0, separator), rendered.substring(separator + 1));
        }
        return result;
    }

    private static String key(int writer, int index) { return "T" + writer + "K" + index; }
    private static String value(int writer, int index) { return "w" + writer + "=" + index; }

    private static String repeat(char value, int count) {
        char[] chars = new char[count];
        Arrays.fill(chars, value);
        return new String(chars);
    }

    private static void assertArrayEquals(String[] expected, String[] actual, String message) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(message + ": expected=" + Arrays.toString(expected)
                    + ", actual=" + Arrays.toString(actual));
        }
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void equals(Object expected, Object actual, String message) {
        if (expected == null ? actual != null : !expected.equals(actual)) {
            throw new AssertionError(message + ": expected=" + expected + ", actual=" + actual);
        }
    }
}

