from collections.abc import Mapping
from copy import deepcopy


def clean_catalog(entries, blocked_directories, blocked_suffixes, scoped_suffixes, dry_run):
    if not isinstance(entries, list):
        raise TypeError("entries must be a list")
    if not isinstance(blocked_directories, (tuple, list, set, frozenset)):
        raise TypeError("blocked_directories must be a collection")
    if not isinstance(blocked_suffixes, (tuple, list, set, frozenset)):
        raise TypeError("blocked_suffixes must be a collection")
    if not isinstance(scoped_suffixes, Mapping):
        raise TypeError("scoped_suffixes must be a mapping")
    if type(dry_run) is not bool:
        raise TypeError("dry_run must be a boolean")

    def validate_strings(values, name):
        for value in values:
            if not isinstance(value, str):
                raise TypeError(f"{name} must contain strings")
            if not value:
                raise ValueError(f"{name} must not contain empty strings")

    validate_strings(blocked_directories, "blocked_directories")
    validate_strings(blocked_suffixes, "blocked_suffixes")
    blocked_dirs = frozenset(blocked_directories)
    endings = tuple(blocked_suffixes)

    scopes = []
    for prefix, suffix_values in scoped_suffixes.items():
        if not isinstance(prefix, tuple):
            raise TypeError("scope prefixes must be tuples")
        if not prefix:
            raise ValueError("scope prefixes must not be empty")
        validate_strings(prefix, "scope prefix")
        if not isinstance(suffix_values, tuple):
            raise TypeError("scoped suffix collections must be tuples")
        validate_strings(suffix_values, "scoped suffixes")
        scopes.append((prefix, suffix_values))

    candidates = []
    for entry in entries:
        if not isinstance(entry, dict):
            raise TypeError("each entry must be a dictionary")
        if set(entry) != {"path", "kind", "metadata"}:
            raise ValueError("each entry must have exactly path, kind, and metadata")
        path = entry["path"]
        kind = entry["kind"]
        if not isinstance(path, tuple):
            raise TypeError("path must be a tuple")
        if not path:
            raise ValueError("path must not be empty")
        validate_strings(path, "path")
        if not isinstance(kind, str):
            raise TypeError("kind must be a string")
        if kind not in {"file", "directory"}:
            raise ValueError("kind must be file or directory")

        candidate = any(component in blocked_dirs for component in path)
        if kind == "file" and not candidate:
            candidate = any(path[-1].endswith(suffix) for suffix in endings)
        if kind == "file" and not candidate:
            for prefix, suffix_values in scopes:
                if path[:len(prefix)] == prefix and any(
                    path[-1].endswith(suffix) for suffix in suffix_values
                ):
                    candidate = True
                    break
        candidates.append(candidate)

    removed = [deepcopy(entry) for entry, candidate in zip(entries, candidates) if candidate]
    if dry_run:
        remaining = [deepcopy(entry) for entry in entries]
    else:
        remaining = [deepcopy(entry) for entry, candidate in zip(entries, candidates) if not candidate]
    return {"removed": removed, "remaining": remaining}

