from collections.abc import Mapping
from copy import deepcopy


class SignalSpec:
    def __init__(self, code, unit, labels=None):
        if not isinstance(code, str):
            raise TypeError("code must be a string")
        if not code:
            raise ValueError("code must not be empty")
        if not isinstance(unit, str):
            raise TypeError("unit must be a string")
        if labels is None:
            labels = {}
        if not isinstance(labels, Mapping):
            raise TypeError("labels must be a mapping")
        self.code = code
        self.unit = unit
        self.labels = deepcopy(dict(labels))


class SignalCatalog:
    def __init__(self, specs=None):
        self._specs = []
        if specs is not None:
            for spec in specs:
                self.add(spec)

    def add(self, spec):
        if not isinstance(spec, SignalSpec):
            raise TypeError("spec must be a SignalSpec")
        if any(existing.code == spec.code for existing in self._specs):
            raise ValueError("duplicate code")
        self._specs.append(deepcopy(spec))

    def all(self):
        return deepcopy(self._specs)

    def find(self, code):
        if not isinstance(code, str):
            raise TypeError("code must be a string")
        for spec in self._specs:
            if spec.code == code:
                return deepcopy(spec)
        return None

