import copy
import re
from collections.abc import Mapping


_SLUG = re.compile(r"[a-z0-9-]+\Z")


class RecipeShelf:
    def __init__(self, recipes=()):
        self._recipes = {}
        for recipe in recipes:
            self.add(recipe)

    @staticmethod
    def _normalize(recipe):
        if not isinstance(recipe, Mapping) or set(recipe) != {"slug", "title", "tags"}:
            raise ValueError("recipe must contain exactly slug, title, and tags")
        slug = recipe["slug"]
        if not isinstance(slug, str) or not _SLUG.fullmatch(slug):
            raise ValueError("invalid slug")
        title = recipe["title"]
        if not isinstance(title, str) or not title.strip():
            raise ValueError("invalid title")
        try:
            tags = list(recipe["tags"])
        except TypeError:
            raise TypeError("tags must be iterable") from None
        if any(not isinstance(tag, str) or not tag.strip() for tag in tags):
            raise ValueError("invalid tag")
        return {"slug": slug, "title": title.strip(), "tags": [tag.strip() for tag in tags]}

    def add(self, recipe):
        normalized = self._normalize(recipe)
        if normalized["slug"] in self._recipes:
            raise ValueError("duplicate slug")
        self._recipes[normalized["slug"]] = normalized

    def edit(self, slug, *, title=None, tags=None):
        if slug not in self._recipes:
            raise KeyError(slug)
        candidate = copy.deepcopy(self._recipes[slug])
        if title is not None:
            candidate["title"] = title
        if tags is not None:
            try:
                candidate["tags"] = list(tags)
            except TypeError:
                raise TypeError("tags must be iterable") from None
        normalized = self._normalize(candidate)
        self._recipes[slug] = normalized
        return copy.deepcopy(normalized)

    def detail(self, slug):
        if slug not in self._recipes:
            raise KeyError(slug)
        return copy.deepcopy(self._recipes[slug])

    def list_all(self):
        return [copy.deepcopy(self._recipes[slug]) for slug in sorted(self._recipes)]

    def resolve(self, path):
        if path == "/":
            return "page", {"message": "Recipe shelf"}
        if path == "/start":
            return "redirect", "/recipes"
        if path == "/recipes":
            return "page", self.list_all()
        prefix = "/recipes/"
        if isinstance(path, str) and path.startswith(prefix) and path[len(prefix):] and "/" not in path[len(prefix):]:
            return "page", self.detail(path[len(prefix):])
        raise KeyError(path)

