from collections.abc import Mapping, Sequence
from copy import deepcopy


def catalog_snapshot(items, collections, page, page_size):
    """Validate and return a detached, consistently ordered catalog page."""
    if (isinstance(page, bool) or not isinstance(page, int) or page <= 0 or
            isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0):
        raise ValueError("page and page_size must be positive integers")

    item_list = []
    by_id = {}
    for item in items:
        if not isinstance(item, Mapping) or set(item) != {"id", "title", "votes"}:
            raise TypeError("invalid item record")
        snapshot = dict(item)
        if not isinstance(snapshot["id"], str) or not snapshot["id"]:
            raise ValueError("item id must be non-empty")
        if not isinstance(snapshot["title"], str) or not snapshot["title"]:
            raise ValueError("item title must be non-empty")
        if isinstance(snapshot["votes"], bool) or not isinstance(snapshot["votes"], int):
            raise TypeError("votes must be an integer")
        if snapshot["id"] in by_id:
            raise ValueError("duplicate item id")
        detached = deepcopy(snapshot)
        item_list.append(detached)
        by_id[detached["id"]] = detached

    collection_list = []
    collection_ids = set()
    for collection in collections:
        if not isinstance(collection, Mapping) or set(collection) != {"id", "name", "item_ids"}:
            raise TypeError("invalid collection record")
        snapshot = dict(collection)
        if not isinstance(snapshot["id"], str) or not snapshot["id"]:
            raise ValueError("collection id must be non-empty")
        if not isinstance(snapshot["name"], str) or not snapshot["name"]:
            raise ValueError("collection name must be non-empty")
        if snapshot["id"] in collection_ids:
            raise ValueError("duplicate collection id")
        item_ids = snapshot["item_ids"]
        if isinstance(item_ids, (str, bytes)) or not isinstance(item_ids, Sequence):
            raise TypeError("item_ids must be a sequence")
        for item_id in item_ids:
            if not isinstance(item_id, str):
                raise TypeError("item IDs must be strings")
            if item_id not in by_id:
                raise ValueError("unknown item id")
        collection_ids.add(snapshot["id"])
        collection_list.append(deepcopy(snapshot))

    ordered_items = sorted(item_list, key=lambda item: (-item["votes"], item["title"], item["id"]))
    ordered_collections = sorted(collection_list, key=lambda value: (value["name"], value["id"]))
    start = (page - 1) * page_size
    stop = start + page_size

    output_collections = []
    for collection in ordered_collections[start:stop]:
        copied = deepcopy(collection)
        copied["resolved_items"] = [deepcopy(by_id[item_id]) for item_id in collection["item_ids"]]
        output_collections.append(copied)

    return {
        "item_total": len(item_list),
        "collection_total": len(collection_list),
        "items": [deepcopy(item) for item in ordered_items[start:stop]],
        "collections": output_collections,
    }

