use std::collections::{BTreeMap, BTreeSet};

pub enum RegistryError {
    InvalidName(String),
    UnknownScope(String),
    Duplicate(String),
}

#[derive(Clone)]
pub struct TagRegistry {
    scopes: BTreeMap<String, BTreeSet<String>>,
}

fn valid_name(name: &str) -> bool {
    let mut bytes = name.bytes();
    match bytes.next() {
        Some(first) if first.is_ascii_alphabetic() || first == b'_' => {}
        _ => return false,
    }
    bytes.all(|byte| byte.is_ascii_alphanumeric() || byte == b'_')
}

impl TagRegistry {
    pub fn new() -> Self {
        Self {
            scopes: BTreeMap::new(),
        }
    }

    pub fn register_scope(&mut self, scope: &str) -> Result<(), RegistryError> {
        if !valid_name(scope) {
            return Err(RegistryError::InvalidName(scope.to_owned()));
        }
        if self.scopes.contains_key(scope) {
            return Err(RegistryError::Duplicate(scope.to_owned()));
        }
        self.scopes.insert(scope.to_owned(), BTreeSet::new());
        Ok(())
    }

    pub fn register_tag(&mut self, scope: &str, tag: &str) -> Result<(), RegistryError> {
        if !valid_name(scope) {
            return Err(RegistryError::InvalidName(scope.to_owned()));
        }
        if !valid_name(tag) {
            return Err(RegistryError::InvalidName(tag.to_owned()));
        }
        let tags = self
            .scopes
            .get_mut(scope)
            .ok_or_else(|| RegistryError::UnknownScope(scope.to_owned()))?;
        if !tags.insert(tag.to_owned()) {
            return Err(RegistryError::Duplicate(format!("{}::{}", scope, tag)));
        }
        Ok(())
    }

    pub fn register_batch(
        &mut self,
        enabled: bool,
        entries: &[(&str, &str)],
    ) -> Result<(), RegistryError> {
        if !enabled {
            return Ok(());
        }
        let mut candidate = self.clone();
        for &(scope, tag) in entries {
            candidate.register_tag(scope, tag)?;
        }
        *self = candidate;
        Ok(())
    }

    pub fn tags(&self) -> Vec<String> {
        let mut result: Vec<String> = self
            .scopes
            .iter()
            .flat_map(|(scope, tags)| {
                tags.iter().map(move |tag| format!("{}::{}", scope, tag))
            })
            .collect();
        result.sort();
        result
    }
}

