#[path = "solution.rs"]
mod solution;

use solution::{Ledger, LedgerError, Transfer};

fn transfer(from: &str, to: &str, amount: u64) -> Transfer {
    Transfer {
        from: from.to_string(),
        to: to.to_string(),
        amount,
    }
}

#[test]
fn creates_origin_and_adds_zero_balance_accounts() {
    assert!(matches!(
        Ledger::new(String::new(), 1),
        Err(LedgerError::EmptyAccount)
    ));

    let mut ledger = match Ledger::new("origin".to_string(), 0) {
        Ok(value) => value,
        Err(_) => panic!("valid origin rejected"),
    };
    assert_eq!(ledger.balance("origin"), Some(0));
    assert_eq!(ledger.total(), 0);
    assert!(ledger.add_account("next".to_string()).is_ok());
    assert_eq!(ledger.balance("next"), Some(0));
    assert_eq!(ledger.balance("missing"), None);
    assert_eq!(ledger.total(), 0);
    assert!(matches!(
        ledger.add_account(String::new()),
        Err(LedgerError::EmptyAccount)
    ));
    assert!(matches!(
        ledger.add_account("next".to_string()),
        Err(LedgerError::DuplicateAccount)
    ));
}

#[test]
fn applies_transfer_without_changing_total_supply() {
    let mut ledger = match Ledger::new("a".to_string(), 10) {
        Ok(value) => value,
        Err(_) => panic!("valid ledger rejected"),
    };
    assert!(ledger.add_account("b".to_string()).is_ok());
    assert!(ledger.apply(&transfer("a", "b", 4)).is_ok());
    assert_eq!(ledger.balance("a"), Some(6));
    assert_eq!(ledger.balance("b"), Some(4));
    assert_eq!(ledger.total(), 10);
}

#[test]
fn failed_individual_transfers_do_not_mutate_balances() {
    let mut ledger = match Ledger::new("a".to_string(), 5) {
        Ok(value) => value,
        Err(_) => panic!("valid ledger rejected"),
    };
    assert!(ledger.add_account("b".to_string()).is_ok());

    assert!(matches!(
        ledger.apply(&transfer("a", "b", 0)),
        Err(LedgerError::ZeroAmount)
    ));
    assert!(matches!(
        ledger.apply(&transfer("a", "a", 1)),
        Err(LedgerError::SameAccount)
    ));
    assert!(matches!(
        ledger.apply(&transfer("missing", "b", 1)),
        Err(LedgerError::UnknownAccount)
    ));
    assert!(matches!(
        ledger.apply(&transfer("a", "missing", 1)),
        Err(LedgerError::UnknownAccount)
    ));
    assert!(matches!(
        ledger.apply(&transfer("a", "b", 6)),
        Err(LedgerError::InsufficientFunds)
    ));
    assert_eq!(ledger.balance("a"), Some(5));
    assert_eq!(ledger.balance("b"), Some(0));
    assert_eq!(ledger.total(), 5);
}

#[test]
fn destination_may_reach_u64_max_exactly() {
    let mut ledger = match Ledger::new("source".to_string(), u64::MAX) {
        Ok(value) => value,
        Err(_) => panic!("valid maximum supply rejected"),
    };
    assert!(ledger.add_account("destination".to_string()).is_ok());
    assert!(ledger
        .apply(&transfer("source", "destination", u64::MAX))
        .is_ok());
    assert_eq!(ledger.balance("source"), Some(0));
    assert_eq!(ledger.balance("destination"), Some(u64::MAX));
    assert_eq!(ledger.total(), u64::MAX);
}

#[test]
fn batch_is_ordered_and_rolls_back_all_prior_transfers() {
    let mut ledger = match Ledger::new("a".to_string(), 10) {
        Ok(value) => value,
        Err(_) => panic!("valid ledger rejected"),
    };
    assert!(ledger.add_account("b".to_string()).is_ok());
    assert!(ledger.add_account("c".to_string()).is_ok());
    let batch = vec![
        transfer("a", "b", 6),
        transfer("a", "c", 5),
        transfer("b", "c", 1),
    ];
    assert!(matches!(
        ledger.apply_batch(&batch),
        Err(LedgerError::InsufficientFunds)
    ));
    assert_eq!(ledger.balance("a"), Some(10));
    assert_eq!(ledger.balance("b"), Some(0));
    assert_eq!(ledger.balance("c"), Some(0));
    assert_eq!(ledger.total(), 10);
}

#[test]
fn successful_and_empty_batches_preserve_total() {
    let mut ledger = match Ledger::new("a".to_string(), 10) {
        Ok(value) => value,
        Err(_) => panic!("valid ledger rejected"),
    };
    assert!(ledger.add_account("b".to_string()).is_ok());
    assert!(ledger.add_account("c".to_string()).is_ok());
    assert!(ledger.apply_batch(&[]).is_ok());
    assert!(ledger
        .apply_batch(&[transfer("a", "b", 7), transfer("b", "c", 2)])
        .is_ok());
    assert_eq!(ledger.balance("a"), Some(3));
    assert_eq!(ledger.balance("b"), Some(5));
    assert_eq!(ledger.balance("c"), Some(2));
    assert_eq!(ledger.total(), 10);
}

