#[path = "solution.rs"]
mod solution;

use solution::{total_column, Cell, ColumnError, Table};

fn table(name: &str, rows: Vec<Vec<Cell>>) -> Table {
    Table {
        name: name.to_string(),
        rows,
    }
}

fn label_for_one_based_ordinal(mut ordinal: u128) -> String {
    assert!(ordinal > 0);
    let mut bytes = Vec::new();
    while ordinal > 0 {
        ordinal -= 1;
        bytes.push(b'A' + (ordinal % 26) as u8);
        ordinal /= 26;
    }
    bytes.reverse();
    bytes.into_iter().map(char::from).collect()
}

#[test]
fn totals_numbers_while_tracking_presence_and_preserving_table_order() {
    let tables = vec![
        table(
            "mixed",
            vec![
                vec![Cell::Number(1.0), Cell::Number(2.5)],
                vec![Cell::Text("x".to_string()), Cell::Text("ignored".to_string())],
                vec![Cell::Empty, Cell::Number(-1.0)],
                vec![Cell::Number(9.0)],
            ],
        ),
        table("absent", vec![vec![Cell::Number(4.0)], vec![]]),
        table("empty-cell", vec![vec![Cell::Number(4.0), Cell::Empty]]),
    ];
    let before = tables.clone();
    let totals = match total_column(&tables, "B") {
        Ok(value) => value,
        Err(_) => panic!("valid label rejected"),
    };
    assert_eq!(totals.len(), 3);
    assert_eq!(totals[0].table_name, "mixed");
    assert!(totals[0].present);
    assert_eq!(totals[0].sum, 1.5);
    assert_eq!(totals[1].table_name, "absent");
    assert!(!totals[1].present);
    assert_eq!(totals[1].sum, 0.0);
    assert!(totals[2].present);
    assert_eq!(totals[2].sum, 0.0);
    assert_eq!(tables, before);
}

#[test]
fn spreadsheet_labels_map_at_z_and_aa_boundary() {
    let mut row = vec![Cell::Empty; 27];
    row[25] = Cell::Number(25.0);
    row[26] = Cell::Number(26.0);
    let tables = vec![table("t", vec![row])];

    let z = match total_column(&tables, "Z") {
        Ok(value) => value,
        Err(_) => panic!("Z was rejected"),
    };
    let aa = match total_column(&tables, "AA") {
        Ok(value) => value,
        Err(_) => panic!("AA was rejected"),
    };
    assert_eq!(z[0].sum, 25.0);
    assert_eq!(aa[0].sum, 26.0);
}

#[test]
fn invalid_labels_are_rejected() {
    for label in ["", "a", "Aa", "A1", " A", "A ", "_", "É"] {
        assert_eq!(
            total_column(&[], label),
            Err(ColumnError::InvalidLabel),
            "{label}"
        );
    }
}

#[test]
fn largest_representable_index_is_valid_and_next_index_overflows() {
    let maximum_index_label =
        label_for_one_based_ordinal((usize::MAX as u128) + 1);

    let empty_totals = match total_column(&[], &maximum_index_label) {
        Ok(value) => value,
        Err(_) => panic!("label for usize::MAX was rejected on empty input"),
    };
    assert!(empty_totals.is_empty());

    let tables = vec![table(
        "tiny",
        vec![vec![], vec![Cell::Number(1.0)], vec![Cell::Empty]],
    )];
    let totals = match total_column(&tables, &maximum_index_label) {
        Ok(value) => value,
        Err(_) => panic!("label for usize::MAX was rejected"),
    };
    assert_eq!(totals.len(), 1);
    assert_eq!(totals[0].table_name, "tiny");
    assert!(!totals[0].present);
    assert_eq!(totals[0].sum, 0.0);

    let overflowing_label =
        label_for_one_based_ordinal((usize::MAX as u128) + 2);
    assert_eq!(
        total_column(&[], &overflowing_label),
        Err(ColumnError::LabelOverflow)
    );
}

#[test]
fn empty_table_input_returns_empty_results() {
    match total_column(&[], "A") {
        Ok(value) => assert!(value.is_empty()),
        Err(_) => panic!("valid label rejected"),
    }
}

