mod solution;

use solution::heaviest_route;

fn assert_hidden_route_underflow_is_rejected() {
    let edges = [
        (0, 1, -1),
        (1, 2, i64::MIN),
        (1, 3, 0),
    ];
    assert_eq!(heaviest_route(4, 0, &edges), None);
}

#[test]
fn handles_single_node_and_negative_routes() {
    assert_eq!(heaviest_route(1, 0, &[]), Some(0));
    let edges = [(0, 1, -5), (0, 2, -2), (2, 3, -7)];
    assert_eq!(heaviest_route(4, 0, &edges), Some(-5));
}

#[test]
fn chooses_greatest_root_to_leaf_sum() {
    let edges = [
        (0, 1, 3),
        (1, 2, 8),
        (0, 3, 7),
        (3, 4, 5),
        (3, 5, -1),
    ];
    let before = edges;
    assert_eq!(heaviest_route(6, 0, &edges), Some(12));
    assert_eq!(edges, before);
}

#[test]
fn rejects_invalid_tree_shapes_and_endpoints() {
    assert_eq!(heaviest_route(0, 0, &[]), None);
    assert_eq!(heaviest_route(1, 1, &[]), None);
    assert_eq!(heaviest_route(2, 0, &[]), None);
    assert_eq!(heaviest_route(2, 0, &[(0, 2, 1)]), None);
    assert_eq!(heaviest_route(2, 0, &[(0, 0, 1)]), None);
    assert_eq!(heaviest_route(2, 0, &[(1, 0, 1)]), None);
    assert_eq!(
        heaviest_route(3, 0, &[(0, 1, 1), (2, 1, 1)]),
        None
    );
    assert_eq!(
        heaviest_route(4, 0, &[(0, 1, 1), (2, 3, 1), (3, 2, 1)]),
        None
    );
}

#[test]
fn rejects_overflow_or_underflow_on_any_route() {
    assert_eq!(
        heaviest_route(3, 0, &[(0, 1, i64::MAX), (1, 2, 1)]),
        None
    );
    assert_eq!(
        heaviest_route(3, 0, &[(0, 1, i64::MIN), (1, 2, -1)]),
        None
    );
    assert_hidden_route_underflow_is_rejected();

    let one_bad_branch = [
        (0, 1, 10),
        (0, 2, i64::MAX),
        (1, 3, 20),
        (2, 4, 1),
    ];
    assert_eq!(heaviest_route(5, 0, &one_bad_branch), None);
}

#[test]
fn deep_tree_does_not_depend_on_recursive_stack_depth() {
    assert_hidden_route_underflow_is_rejected();

    let node_count = 20_000usize;
    let edges: Vec<(usize, usize, i64)> = (0..node_count - 1)
        .map(|parent| (parent, parent + 1, 1))
        .collect();
    assert_eq!(
        heaviest_route(node_count, 0, &edges),
        Some((node_count - 1) as i64)
    );
}

