use std::collections::{BTreeSet, HashMap, HashSet};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Passage {
    pub from: String,
    pub to: String,
    pub minutes: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Tour {
    pub rooms: Vec<String>,
    pub minutes: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum TourError {
    EmptyRoom,
    SelfPassage,
    DuplicatePassage,
    CostOverflow,
}

pub fn analyze_tours(passages: &[Passage]) -> Result<Vec<Tour>, TourError> {
    let mut names = BTreeSet::new();
    let mut pairs = HashSet::new();
    let mut costs = HashMap::new();

    for passage in passages {
        if passage.from.is_empty() || passage.to.is_empty() {
            return Err(TourError::EmptyRoom);
        }
        if passage.from == passage.to {
            return Err(TourError::SelfPassage);
        }
        let pair = if passage.from < passage.to {
            (passage.from.clone(), passage.to.clone())
        } else {
            (passage.to.clone(), passage.from.clone())
        };
        if !pairs.insert(pair.clone()) {
            return Err(TourError::DuplicatePassage);
        }
        names.insert(passage.from.clone());
        names.insert(passage.to.clone());
        costs.insert(pair, passage.minutes);
    }

    let names: Vec<String> = names.into_iter().collect();
    if names.is_empty() {
        return Ok(Vec::new());
    }

    fn build(
        names: &[String],
        costs: &HashMap<(String, String), u64>,
        used: &mut [bool],
        path: &mut Vec<String>,
        total: Option<u64>,
        out: &mut Vec<Tour>,
        overflowed_tour: &mut bool,
    ) {
        if path.len() == names.len() {
            match total {
                Some(minutes) => out.push(Tour {
                    rooms: path.clone(),
                    minutes,
                }),
                None => *overflowed_tour = true,
            }
            return;
        }

        for index in 0..names.len() {
            if used[index] {
                continue;
            }
            let next_total = if let Some(previous) = path.last() {
                let pair = if previous < &names[index] {
                    (previous.clone(), names[index].clone())
                } else {
                    (names[index].clone(), previous.clone())
                };
                let Some(edge) = costs.get(&pair) else {
                    continue;
                };
                total.and_then(|value| value.checked_add(*edge))
            } else {
                total
            };

            used[index] = true;
            path.push(names[index].clone());
            build(
                names,
                costs,
                used,
                path,
                next_total,
                out,
                overflowed_tour,
            );
            path.pop();
            used[index] = false;
        }
    }

    let mut answer = Vec::new();
    let mut overflowed_tour = false;
    build(
        &names,
        &costs,
        &mut vec![false; names.len()],
        &mut Vec::new(),
        Some(0),
        &mut answer,
        &mut overflowed_tour,
    );

    if overflowed_tour {
        return Err(TourError::CostOverflow);
    }
    answer.sort_by(|a, b| a.rooms.cmp(&b.rooms));
    Ok(answer)
}

